function More({groups,students,events,setGroups,setEvents,onCsv,onBackup,onRestore}:{groups:Group[];students:Student[];events:Event[];setGroups:React.Dispatch<React.SetStateAction<Group[]>>;setEvents:React.Dispatch<React.SetStateAction<Event[]>>;onCsv:()=>void;onBackup:()=>void;onRestore:(f?:File)=>void}){const [form,setForm]=useState<'group'|'event'|null>(null),[edit,setEdit]=useState<Group|null>(null);return <><section className="panel"><div className="panel-title"><h2>Группы</h2><button className="primary" onClick={()=>{setEdit(null);setForm('group')}}>＋ Группа</button></div>{groups.map(g=><div className="group-row" key={g.id}><span><b>{g.name}</b><small>{g.days.map(d=>['Вс','Пн','Вт','Ср','Чт','Пт','Сб'][d]).join(' · ')} · {g.time}</small></span><i>{students.filter(s=>s.groupId===g.id).length} уч.</i><button className="secondary" onClick={()=>{setEdit(g);setForm('group')}}>Изменить</button><button className="delete" onClick={()=>confirm('Удалить группу?')&&setGroups(x=>x.filter(a=>a.id!==g.id))}>×</button></div>)}</section><section className="panel"><div className="panel-title"><h2>Соревнования</h2><button className="primary" onClick={()=>setForm('event')}>＋ Добавить</button></div>{events.map(e=><div className="group-row" key={e.id}><span><b>{e.name}</b><small>{e.date}{e.endDate&&e.endDate!==e.date?' — '+e.endDate:''}</small><small>{e.place}</small></span><i>{Object.keys(e.participants).length} участников</i></div>)}</section><section className="panel menu"><h2>Данные</h2><button onClick={onCsv}>↥　Экспорт CSV<b>›</b></button><button onClick={onBackup}>⇩　Резервная копия JSON<b>›</b></button><label className="restore">⇧　Восстановить копию<input type="file" accept="application/json" onChange={e=>onRestore(e.target.files?.[0])}/><b>›</b></label></section>{form==='group'&&<Modal title={edit?'Изменить группу':'Новая группа'} close={()=>setForm(null)}><form onSubmit={e=>{e.preventDefault();const d=new FormData(e.currentTarget),g={id:edit?.id||id(),name:String(d.get('name')),days:d.getAll('days').map(Number),time:String(d.get('time')),hall:String(d.get('hall')),fee:Number(d.get('fee'))};setGroups(x=>edit?x.map(a=>a.id===edit.id?g:a):[...x,g]);setForm(null)}}><F l="Название" n="name" v={edit?.name}/><F l="Время" n="time" t="time" v={edit?.time||'18:00'}/><F l="Зал" n="hall" v={edit?.hall}/><F l="Оплата, ₽" n="fee" t="number" v={edit?String(edit.fee):''}/><label>Дни недели<div className="days">{['Вс','Пн','Вт','Ср','Чт','Пт','Сб'].map((x,i)=><label key={x}><input name="days" type="checkbox" value={i} defaultChecked={edit?.days.includes(i)}/>{x}</label>)}</div></label><button className="primary submit">Сохранить</button></form></Modal>}{form==='event'&&<Modal title="Соревнование" close={()=>setForm(null)}><form onSubmit={e=>{e.preventDefault();const d=new FormData(e.currentTarget),participants:Record<string,string>={};students.forEach(s=>{const r=String(d.get('r-'+s.id)||'');if(r)participants[s.id]=r});setEvents(x=>[...x,{id:id(),name:String(d.get('name')),date:String(d.get('date')),place:String(d.get('place')),participants}]);setForm(null)}}><F l="Название" n="name"/><F l="Дата" n="date" t="date"/><F l="Место" n="place"/>{students.map(s=><label key={s.id}>{s.name}<select name={'r-'+s.id}><option value="">Не участвует</option><option>1 место · золото</option><option>2 место · серебро</option><option>3 место · бронза</option><option>Участник</option></select></label>)}<button className="primary submit">Сохранить</button></form></Modal>}</>}

function MoreV2({groups,students,events,trainings,setGroups,setStudents,setEvents,onCsv,onBackup,onRestore}:{groups:Group[];students:Student[];events:Event[];trainings:Training[];setGroups:React.Dispatch<React.SetStateAction<Group[]>>;setStudents:React.Dispatch<React.SetStateAction<Student[]>>;setEvents:React.Dispatch<React.SetStateAction<Event[]>>;onCsv:()=>void;onBackup:()=>void;onRestore:(f?:File)=>void}){const importCsv=(file?:File)=>{if(!file)return;const r=new FileReader();r.onload=()=>{const rows=String(r.result).replace(/^\uFEFF/,'').split(/\r?\n/).slice(1).filter(Boolean);const added:Student[]=rows.map((row,i):Student=>{const c=row.split(/[;,]/).map(x=>x.trim());return{id:id(),name:c[0],birth:c[2]||'',parent:c[3]||'',groupId:groups.find(g=>g.name===c[1])?.id||groups[0]?.id||'',status:'Активен',note:'Импортировано',color:colours[(students.length+i)%colours.length]}}).filter(s=>s.name);setStudents(x=>[...x,...added]);alert('Импортировано учеников: '+added.length)};r.readAsText(file)};const exportAll=()=>{const trainingRows=trainings.map(t=>t.date+';'+(groups.find(g=>g.id===t.groupId)?.name||'')+';'+t.time+';'+(t.cancelled?'отменена':'активна'));const eventRows=events.map(e=>e.date+';'+e.name+';'+e.place+';'+Object.keys(e.participants).length+' участников');const data='Тренировки\n'+trainingRows.join('\n')+'\n\nСоревнования\n'+eventRows.join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+data],{type:'text/csv'}));a.download='журналы-клуба.csv';a.click()};return <><MediaLibrary groups={groups} events={events}/><More groups={groups} students={students} events={events} setGroups={setGroups} setEvents={setEvents} onCsv={onCsv} onBackup={onBackup} onRestore={onRestore}/><section className="panel menu"><h2>Импорт и журналы</h2><label className="restore">⇧　Импорт учеников из CSV<input type="file" accept=".csv,text/csv" onChange={e=>importCsv(e.target.files?.[0])}/><b>›</b></label><button onClick={exportAll}>↥　Экспорт тренировок и соревнований<b>›</b></button><p className="muted">CSV: первая строка — заголовки; порядок полей: ФИО, группа, дата рождения, телефон родителя.</p></section></>}

type MediaSlot={id:string;title:string;hint:string};
function MediaLibrary({groups,events}:{groups:Group[];events:Event[]}){const base:MediaSlot[]=[{id:'cover',title:'Обложка клуба',hint:'Горизонтальная фотография для главного экрана'},{id:'trainer',title:'Фото тренера',hint:'Портрет для профиля клуба'},{id:'logo',title:'Логотип клуба',hint:'PNG, JPG или SVG'}];const slots=[...base,...groups.map(g=>({id:'group-'+g.id,title:'Группа: '+g.name,hint:'Фото группы или тренировки'})),...events.map(e=>({id:'event-'+e.id,title:'Соревнование: '+e.name,hint:'Фото события'}))];const [images,setImages]=useState<Record<string,string>>(()=>read('media',{}));const loadImage=(slot:string,file?:File)=>{if(!file)return;if(!file.type.startsWith('image/'))return alert('Выберите изображение');if(file.size>900000)return alert('Для локальной версии выберите фото до 900 КБ');const reader=new FileReader();reader.onload=()=>{const next={...images,[slot]:String(reader.result)};setImages(next);localStorage.setItem('club-final-media',JSON.stringify(next))};reader.readAsDataURL(file)};const remove=(slot:string)=>{const next={...images};delete next[slot];setImages(next);localStorage.setItem('club-final-media',JSON.stringify(next))};return <section className="panel media-library"><div className="panel-title"><div><p className="eyebrow">Оформление</p><h2>Фотографии и логотип</h2></div></div><p className="muted">Выберите изображения прямо на телефоне или компьютере. Они остаются в браузере этого устройства до подключения сервера.</p><div className="media-grid">{slots.map(slot=><div className="media-slot" key={slot.id}>{images[slot.id]?<img src={images[slot.id]} alt={slot.title}/>:<div className="media-placeholder">▧</div>}<div><b>{slot.title}</b><small>{slot.hint}</small><label className="upload">Выбрать фото<input type="file" accept="image/png,image/jpeg,image/webp,image/svg+xml" onChange={e=>loadImage(slot.id,e.target.files?.[0])}/></label>{images[slot.id]&&<button className="remove-media" onClick={()=>remove(slot.id)}>Удалить</button>}</div></div>)}</div></section>}
